from openpyxl import load_workbook
from openpyxl.cell.cell import Cell
wb=load_workbook('/root/data/test-rar.xlsx', data_only=False)
errs=[]
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for cell in row:
            if cell.data_type=='e':
                errs.append((ws.title, cell.coordinate, cell.value))
print('error cells',len(errs))
for e in errs[:50]:
    print(e)
PY"}

{"summary": "Search workbook formulas for likely syntax issues like '*='", "security_risk": "LOW", "command": "python3 - <<'PY'
from openpyxl import load_workbook
wb=load_workbook('/root/output/rar_result.xlsx', data_only=False)
bad=[]
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for cell in row:
            v=cell.value
            if isinstance(v,str) and v.startswith('=') and '*=' in v:
                bad.append((ws.title, cell.coordinate, v))
print('bad',len(bad))
for b in bad[:20]:
    print(b)
PY"}

